 public sealed class Stage56Benchmark:MonoBehaviour
 {
  [Serializable]public class Frame{public string phase;public double interval,display,mutation,decorations;public long allocation;public int resident,meshes,revision;public bool ready;}
  [Serializable]public class Event{public string name;public double ms;public string result;}
  [Serializable]public class Resource{public string name;public long managed,unity;public int meshes,resident;}
  [Serializable]public class Result{public string error="",hardware;public List<Frame> frames=new List<Frame>();public List<Event> events=new List<Event>();public List<Resource> resources=new List<Resource>();public List<string> checks=new List<string>();}
  Stage56Preview camp;string output;Result result=new Result();ProfilerRecorder alloc;
  IEnumerator Start(){var args=Environment.GetCommandLineArgs();int n=Array.IndexOf(args,"-stage56Output");if(n<0)yield break;output=args[n+1];Directory.CreateDirectory(output);camp=GetComponent<Stage56Preview>();camp.Initialize();camp.automation=true;camp.showPanel=false;camp.Live.automation=true;camp.Session.Committed+=b=>RecordEvent("mesh-batch:"+b.Reason,camp.MutationMs,"accepted cells="+b.Cells.Count);QualitySettings.vSyncCount=0;Application.targetFrameRate=60;Application.runInBackground=true;result.hardware=SystemInfo.processorType+" / "+SystemInfo.graphicsDeviceName+" / "+SystemInfo.graphicsDeviceType;alloc=ProfilerRecorder.StartNew(ProfilerCategory.Memory,"GC Allocated In Frame");double initialStart=Time.realtimeSinceStartupAsDouble;yield return Settle();RecordEvent("initial-geometry-ready",(Time.realtimeSinceStartupAsDouble-initialStart)*1000,"Streaming readiness wait after scene initialization");RecordEvent("definition",camp.DefinitionMs,"complete authored192 squared");RecordEvent("initialization",camp.ResetMs,"session + setup, excludes streaming readiness");ResourceSample("initial");for(int probe=0;probe<3;probe++){var bytes=new byte[1048576];bytes[0]=1;yield return null;RecordEvent("allocation-probe",alloc.Valid?alloc.LastValue:-1,"bytes observed for1MiB allocation; completed-frame recorder");GC.KeepAlive(bytes);}yield return Capture("01-first-arrival");
   camp.Go("fire");yield return Settle();yield return Capture("02-fire-reference62");camp.SetFraming(1);yield return Settle();yield return Capture("03-fire-alternative57");camp.SetFraming(0);yield return Frames("camera-warm",180);
   camp.Session.Discover();camp.returnBuddies=3;long t=System.Diagnostics.Stopwatch.GetTimestamp();camp.FakeReturn();RecordEvent("fake-return",StreamingGeometry.Elapsed(t),"3 buddies;5 mushrooms;2 shinies");yield return Settle();yield return Capture("04-first-buddy-squad");camp.Go("fire");yield return Settle();
   yield return Capture("04b-fire-before-bedroom-excavation");Probe("early-entrance-west",camp.Session.Definition.Bedrooms[0].Entrance);Probe("early-entrance-east",camp.Session.Definition.Bedrooms[1].Entrance);
   for(int i=0;i<3;i++){t=System.Diagnostics.Stopwatch.GetTimestamp();camp.DigBedrooms();RecordEvent("bedroom-"+(i+1),StreamingGeometry.Elapsed(t),camp.Status);int constructionGuard=0;bool capturedDig=false;int beforeRevision=camp.Session.Revision;while(camp.Constructing&&constructionGuard++<20000){double tick=Time.realtimeSinceStartupAsDouble;camp.TickResidents(Math.Min(.05,Time.unscaledDeltaTime));yield return null;RecordFrame("bedroom-live",(Time.realtimeSinceStartupAsDouble-tick)*1000);if(i==0&&!capturedDig&&camp.Session.Revision>beforeRevision+5){capturedDig=true;yield return Settle();Probe("fire-visible-worker-during-dig",camp.Session.Construction.Worker.Position);yield return Capture("04c-fire-during-bedroom-excavation");}}Check(camp.Session.Established==i+1,"Bed established "+(i+1)+" "+camp.Session.ConstructionStatus);yield return Settle();}camp.Go("fire");yield return Capture("05-three-residents");var room=camp.Session.Definition.Bedrooms[0];camp.Live.Teleport(Stage56Preview.V(room.Beds[1]));camp.Live.SetPreviewFocus(camp.Live.Position);yield return Settle();yield return Capture("06-shared-bedroom");
   camp.Go("bones");yield return Settle();Check(!camp.Session.Active(CampCell.FirstDeath),"Bones interaction locked before death despite reachable niche");camp.categoryOverlay=true;yield return Capture("06b-bones-exit-terrain-authorization");camp.categoryOverlay=false;camp.Session.BuddyDied();yield return Settle();camp.Go("bones");yield return Settle();yield return Capture("07-first-death-bones");camp.Session.AddBuddy();Check(camp.Session.Established==3,"Death vacancy reuse without new bed");
   for(int i=0;i<7;i++)camp.Session.AddBuddy();for(int i=3;i<10;i++){t=System.Diagnostics.Stopwatch.GetTimestamp();bool ok;string why;if(i==3){camp.Go("fire");yield return Settle();yield return Capture("07b-fire-before-second-pocket");camp.DigBedrooms();int revision=camp.Session.Revision;bool captured=false;int guard=0;while(camp.Constructing&&guard++<20000){camp.TickResidents(Math.Min(.05,Time.unscaledDeltaTime));yield return null;if(!captured&&camp.Session.Revision>revision+5){captured=true;yield return Settle();Probe("fire-visible-east-worker-during-dig",camp.Session.Construction.Worker.Position);yield return Capture("07c-fire-during-second-pocket");}}ok=camp.Session.Established==4;why=camp.Session.ConstructionStatus;}else ok=camp.Session.ConstructNext(out why);RecordEvent(i==3?"second-pocket-live-wall-time":"later-bedroom-"+(i+1),StreamingGeometry.Elapsed(t),why);Check(ok,"Later bed "+(i+1)+" "+why);}yield return Settle();camp.Live.Teleport(Stage56Preview.V(camp.Session.Definition.Bedrooms[3].Beds[0]));camp.Live.SetPreviewFocus(camp.Live.Position);yield return Settle();yield return Capture("08-later-neighborhood");ResourceSample("grown");
   camp.Go("squad");yield return Settle();camp.categoryOverlay=true;yield return Capture("08b-squad-central-earth-authorization");camp.categoryOverlay=false;
   foreach(var marker in camp.Session.Definition.Markers)if(camp.Session.Active(marker.Gate)){camp.Go(marker.Id);yield return Settle();yield return Capture("09-station-"+marker.Id.Replace('.','-'));}camp.Go("fire");yield return Settle();camp.Session.Recover();yield return Frames("grown-camera-travel",360,true);
   camp.Live.Teleport(new Vector2(76.5f,103.5f));Check(Vector2.Distance(camp.Live.Position,new Vector2(76.5f,103.5f))<.01f,"Excavation probe starts at reachable open approach");camp.Live.SetPreviewFocus(camp.Live.Position);yield return Settle();for(int i=0;i<3;i++){t=System.Diagnostics.Stopwatch.GetTimestamp();int cut=camp.Dig(new Point2(camp.Live.Position.x,camp.Live.Position.y+1.6));RecordEvent("ordinary-expansion-dig-"+i,StreamingGeometry.Elapsed(t),"accepted cells="+cut);Check(cut>0,"Reachable player excavation accepts batch "+i);var advanced=camp.Session.Move(Stage56Preview.P(camp.Live.Position),new Point2(0,1),1);camp.Live.TeleportWithoutFocus(Stage56Preview.V(advanced));yield return null;}Check(camp.Session.Route(camp.Session.Definition.Marker("fire").Interaction,Stage56Preview.P(camp.Live.Position),1).Count>0,"Player can walk from Fire into actual excavated area");yield return Capture("09b-local-excavation");
   for(int i=0;i<3;i++){t=System.Diagnostics.Stopwatch.GetTimestamp();camp.FakeReturn();RecordEvent("repeated-fake-return-"+i,StreamingGeometry.Elapsed(t),camp.Status);yield return Settle();}
   Check(Type.GetType("GameState, Assembly-CSharp").GetProperty("Instance").GetValue(null)==null,"No GameState registration");Check(Type.GetType("DiggableTerrainService, Assembly-CSharp").GetProperty("Active").GetValue(null)==null,"No production terrain registration");
   for(int i=0;i<5;i++){t=System.Diagnostics.Stopwatch.GetTimestamp();camp.ResetTest(i%3);RecordEvent("reset-"+i,StreamingGeometry.Elapsed(t),"snapshot"+(i%3));yield return Settle();ResourceSample("reset-"+i);}camp.showPanel=true;yield return Capture("10-testing-panel");Check(camp.Live.World.Width==192,"Complete authored world installed");Check(camp.Session.Definition.Capacity==10,"Ten unique beds / four pockets");File.WriteAllText(Path.Combine(output,"result.json"),JsonUtility.ToJson(result,true));alloc.Dispose();Application.Quit(result.error==""?0:1);
  }
  void Probe(string name,Point2 p){
   var screen=camp.ScreenPoint(p);bool inside=screen.x>24&&screen.x<Screen.width-24&&screen.y>24&&screen.y<Screen.height-24;
   int clear=0,total=15;for(int y=0;y<3;y++)for(int x=0;x<5;x++){var q=camp.Live.Snapshot.Project(new Point2(p.X+(x-2)*.4,p.Y-y*.5));if(!Covered(q))clear++;}
   RecordEvent("screen-proof:"+name,0,$"logical=({p.X:F2},{p.Y:F2}); screen=({screen.x:F1},{screen.y:F1})/{Screen.width}x{Screen.height}; clear wall/lip samples={clear}/{total}; centerWidth={camp.Live.settings.centerWidth}; coverage={camp.Live.settings.coverage}; anchor={camp.Live.settings.anchor}; wallHeight={camp.Live.settings.wallHeight}");
   Check(inside&&clear>=5,name+" within normal Fire viewport with readable wall-clear samples");
  }
  bool Covered(Point2 p){foreach(var c in camp.Live.Stream.Resident.Values)foreach(var d in c.Layers)if(d.Layer==PreviewLayer.Faces||d.Layer==PreviewLayer.Lips){for(int i=0;i<d.Indices.Count;i+=3){var a=Resolve(d,d.Indices[i]);var b=Resolve(d,d.Indices[i+1]);var z=Resolve(d,d.Indices[i+2]);double ab=Cross(a,b,p),bc=Cross(b,z,p),ca=Cross(z,a,p);if((ab>1e-7&&bc>1e-7&&ca>1e-7)||(ab< -1e-7&&bc< -1e-7&&ca< -1e-7))return true;}}return false;}
  Point2 Resolve(PreviewMeshData d,int index){var v=d.LogicalVertices[index];if(v.WallSampleIndex<0)return camp.Live.Snapshot.Project(v.Logical);var w=WallGeometry.Project(d.WallSamples[v.WallSampleIndex],camp.Live.Snapshot,new WallSettings(camp.Live.settings.wallHeight,.22),camp.Live.settings.heightPolicy);return v.Role==GeometryVertexRole.WallBottom?w.Bottom:v.Role==GeometryVertexRole.ForegroundLip?w.Lip:w.Top;}
  static double Cross(Point2 a,Point2 b,Point2 c)=>(b.X-a.X)*(c.Y-a.Y)-(b.Y-a.Y)*(c.X-a.X);
  void Check(bool ok,string label){result.checks.Add((ok?"PASS ":"FAIL ")+label);if(!ok)result.error+=label+"; ";}
  void RecordEvent(string name,double ms,string detail){result.events.Add(new Event{name=name,ms=ms,result=detail});}
  IEnumerator Settle(){int i=0;do{yield return null;if(++i>3000){Check(false,"readiness timeout");yield break;}}while(!camp.Live.Ready);for(i=0;i<3;i++)yield return null;}
  IEnumerator Frames(string phase,int count,bool moving=false){for(int i=0;i<count;i++){double t=Time.realtimeSinceStartupAsDouble;if(moving){camp.TickResidents(Math.Min(.05,Time.unscaledDeltaTime));var p=camp.Live.Position;var delta=new Point2(Math.Sin(i*.03)*.05,Math.Cos(i*.03)*.05);var q=camp.Session.Move(Stage56Preview.P(p),delta,1);camp.Live.TeleportWithoutFocus(Stage56Preview.V(q));}yield return null;RecordFrame(phase,(Time.realtimeSinceStartupAsDouble-t)*1000);}}
  void RecordFrame(string phase,double interval){result.frames.Add(new Frame{phase=phase,interval=interval,display=camp.Live.DisplayMs,mutation=camp.MutationMs,decorations=camp.DecorationMs,allocation=alloc.Valid?alloc.LastValue:-1,resident=camp.Live.Stream.Resident.Count,meshes=camp.Live.MeshCount+4,revision=camp.Session.Revision,ready=camp.Live.Ready});}
  IEnumerator Capture(string name){yield return Settle();camp.CameraStudy.Capture(output,name);while(camp.CameraStudy.CapturePending)yield return null;camp.CameraStudy.captureLabel=false;}
  void ResourceSample(string name){GC.Collect();result.resources.Add(new Resource{name=name,managed=GC.GetTotalMemory(true),unity=UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong(),meshes=camp.Live.MeshCount+4,resident=camp.Live.Stream.Resident.Count});}
 }
